styles:
body { max-width: 76rem; margin: 0 auto; padding: 1rem; font: 1rem/1.5 system-ui, sans-serif; color: #222; background: #fff; overflow-wrap: anywhere; }
pre { white-space: pre-wrap; overflow-wrap: anywhere; font: 0.95rem/1.45 ui-monospace, monospace; }
details { margin: 0.75rem 0; padding: 0.75rem; border: 1px solid #bbb; border-radius: 0.3rem; }
summary { cursor: pointer; font-weight: 600; }
dt { font-weight: 600; }
dd { margin-left: 1rem; }
nav { margin: 1rem 0; }
